'use client'

import { createPortal } from 'react-dom'
import { CurlStage } from './curl-stage'
import { FlipSheet } from './flip-sheet'
import { useNarrowLayout } from '../media'
import { pageSearchText } from '../normalize'
import { Input } from '@/components/ui/input'
import { CurlPdfSheet } from './curl-pdf-sheet'
import { Button } from '@/components/ui/button'
import { Spinner } from '@/components/ui/spinner'
import { resolvePdfOutline } from '../pdf-runtime'
import { buildPremierFaces } from './premier-faces'
import { PdfPasswordGate } from './pdf-password-gate'
import { PdfPreparingBadge } from './pdf-preparing-badge'
import { useBookPreview } from '../book-preview-provider'
import { BookPreviewPageView } from '../book-preview-page'
import { PdfThumbRail, PdfThumbSheet } from './pdf-thumb-rail'
import { useStableHandler } from '../hooks/use-stable-handler'
import { usePdfSheets, type PdfSheet } from '../hooks/use-pdf-sheets'
import { DEFAULT_CAPABILITIES, hasSpeechSupport } from '../capabilities'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group'
import {
  CURL_MAX_PAGES,
  CURL_PAGE_RATIO,
  CURL_RASTER_WIDTH,
} from './curl-geometry'
import {
  readBookPreviewPrefs,
  writeBookPreviewPrefs,
  type PremierView,
} from '../prefs'
import {
  PremierScrollView,
  PremierSingleView,
  PremierSpreadView,
  PremierTextView,
} from './premier-views'
import type {
  BookPreviewCapabilities,
  BookPreviewEngineProps,
  BookPreviewError,
  BookPreviewPage,
  NormalizedBookSource,
} from '../types'
import {
  BookOpenIcon,
  Columns2Icon,
  FileUpIcon,
  PanelLeftIcon,
  RectangleVerticalIcon,
  ScrollIcon,
  SearchIcon,
  SpeechIcon,
  SquareIcon,
  TypeIcon,
  XIcon,
  ZoomInIcon,
  ZoomOutIcon,
} from 'lucide-react'

// Page chips keep search honest in a raster book — there is no text layer to
// highlight, so results name the pages worth flipping to. Past this count a
// summary stands in for the rest.
const MATCH_CHIP_LIMIT = 20
// Roughly 15 characters per second of speech, plus slack, bounds a page's
// narration. Chrome can silently drop onend for long utterances — the
// watchdog below forces the same advance path when that happens.
const SPEECH_CHARS_PER_SECOND = 15
const SPEECH_WATCHDOG_SLACK_MS = 8000

function premierCapabilities(
  source: NormalizedBookSource,
  usePdf: boolean,
): BookPreviewCapabilities {
  return {
    ...DEFAULT_CAPABILITIES,
    curl: true,
    search: true,
    speech: hasSpeechSupport(),
    // The document brings its own paper; ours would fight the scan.
    appearance: !usePdf,
    thumbnails: usePdf,
    download: Boolean(source.downloadUrl || source.pdfUrl),
    upload: !usePdf ? false : source.allowPdfUpload,
  }
}

/**
 * Continuous read-aloud: narrates the current page, turns when the utterance
 * ends, and skips silent pages so an image spread never stalls the story. A
 * manual turn mid-reading simply re-reads the page you land on.
 */
function useReadAloud({
  totalPages,
  pageIndex,
  textFor,
  onPageChange,
}: {
  totalPages: number
  pageIndex: number
  textFor: (index: number) => string
  onPageChange: (index: number) => void
}) {
  const [speaking, setSpeaking] = useState(false)
  const speakingRef = useRef(false)
  const utteranceRef = useRef<SpeechSynthesisUtterance | null>(null)
  const watchdogRef = useRef<number | null>(null)
  const textForRef = useRef(textFor)
  const pageIndexRef = useRef(pageIndex)
  const totalPagesRef = useRef(totalPages)
  const reportPageChange = useStableHandler(onPageChange)

  useEffect(() => {
    textForRef.current = textFor
    pageIndexRef.current = pageIndex
    totalPagesRef.current = totalPages
  })

  const clearWatchdog = useCallback(() => {
    if (watchdogRef.current !== null) {
      window.clearTimeout(watchdogRef.current)
      watchdogRef.current = null
    }
  }, [])

  const stop = useCallback(() => {
    speakingRef.current = false
    setSpeaking(false)
    utteranceRef.current = null
    clearWatchdog()
    if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
      window.speechSynthesis.cancel()
    }
  }, [clearWatchdog])

  const stopRef = useRef(stop)
  useEffect(() => {
    stopRef.current = stop
  })

  // Narrate whatever page is current while `speaking` is on — turns arrive
  // here as pageIndex changes, so reading follows the book.
  useEffect(() => {
    if (
      !speaking ||
      typeof window === 'undefined' ||
      !('speechSynthesis' in window)
    ) {
      return
    }
    window.speechSynthesis.cancel()
    clearWatchdog()
    const text = textForRef.current(pageIndex)
    if (!text.trim()) {
      // A silent page (plate, blank leaf) flips itself rather than stall.
      if (pageIndex < totalPagesRef.current - 1) {
        reportPageChange(pageIndex + 1)
        return
      }
      stopRef.current()
      return
    }
    const utterance = new SpeechSynthesisUtterance(text)
    utteranceRef.current = utterance
    const finish = () => {
      if (utteranceRef.current !== utterance || !speakingRef.current) return
      utteranceRef.current = null
      clearWatchdog()
      const at = pageIndexRef.current
      if (at < totalPagesRef.current - 1) {
        reportPageChange(at + 1)
        return
      }
      stopRef.current()
    }
    utterance.addEventListener('end', finish)
    utterance.addEventListener('error', finish)
    window.speechSynthesis.speak(utterance)
    // Chrome's speech queue can drop onend on long text; a bounded watchdog
    // makes the same advance decision so reading never parks on a page.
    watchdogRef.current = window.setTimeout(
      finish,
      (text.length / SPEECH_CHARS_PER_SECOND) * 1000 + SPEECH_WATCHDOG_SLACK_MS,
    )
    return () => {
      utterance.removeEventListener('end', finish)
      utterance.removeEventListener('error', finish)
      if (utteranceRef.current === utterance) {
        utteranceRef.current = null
        window.speechSynthesis.cancel()
      }
      clearWatchdog()
    }
  }, [clearWatchdog, pageIndex, reportPageChange, speaking])

  // Speech must not outlive the engine.
  useEffect(() => {
    return () => stopRef.current()
  }, [])

  const toggle = useCallback(() => {
    if (speakingRef.current) {
      stopRef.current()
      return
    }
    speakingRef.current = true
    setSpeaking(true)
  }, [])

  return { speaking, toggle, stop }
}

type PageMatch = { index: number; label: string }

function PremierSheets({
  usePdf,
  sheets,
  pages,
  appearance,
}: {
  usePdf: boolean
  sheets: PdfSheet[] | null
  pages: BookPreviewPage[]
  appearance: BookPreviewEngineProps['appearance']
}) {
  if (usePdf && sheets) {
    return sheets.map((sheet) => (
      <FlipSheet key={sheet.id}>
        <CurlPdfSheet src={sheet.src} />
      </FlipSheet>
    ))
  }
  return pages.map((page, index) => (
    <FlipSheet key={page.id}>
      <BookPreviewPageView
        page={page}
        appearance={appearance}
        isLeftPage={index % 2 === 1}
      />
    </FlipSheet>
  ))
}

export default function PremierEngine({
  source,
  pageIndex,
  appearance,
  soundEnabled,
  reducedMotion,
  onPageChange,
  onReady,
  onError,
}: BookPreviewEngineProps) {
  const pages = source.pages
  const pdfUrl = source.pdfUrl
  const usePdf = Boolean(pdfUrl) && pages.length === 0
  const reportReady = useStableHandler(onReady)
  const reportError = useStableHandler(onError)
  const reportPageChange = useStableHandler(onPageChange)
  const { engineShortcutsRef, uploadPdf, chromeHost } = useBookPreview()
  const narrow = useNarrowLayout()
  const fileInputRef = useRef<HTMLInputElement | null>(null)
  const searchInputRef = useRef<HTMLInputElement | null>(null)

  const [searchOpen, setSearchOpen] = useState(false)
  const [query, setQuery] = useState('')
  const [thumbsOpen, setThumbsOpen] = useState(false)

  // The layout is the reader's setting — a remembered choice wins, then a
  // one-page view on narrow screens, and the flip book everywhere else.
  const [view, setView] = useState<PremierView>(
    () => readBookPreviewPrefs().premierView ?? (narrow ? 'single' : 'book'),
  )
  const [zoom, setZoom] = useState(1)
  const zoomIn = useCallback(
    () => setZoom((z) => Math.min(2.4, Math.round((z + 0.2) * 10) / 10)),
    [],
  )
  const zoomOut = useCallback(
    () => setZoom((z) => Math.max(0.6, Math.round((z - 0.2) * 10) / 10)),
    [],
  )
  const zoomReset = useCallback(() => setZoom(1), [])

  const setViewPref = useCallback((next: PremierView) => {
    setView(next)
    writeBookPreviewPrefs({ premierView: next })
  }, [])

  const bookView = view === 'book'

  // A pdf-render failure in book view is almost always the flip-book page cap
  // — bounded views still open the document, so drop down instead of failing.
  const reportSheetsError = useStableHandler((error: BookPreviewError) => {
    if (view === 'book' && error.kind === 'pdf-render') {
      setView('single')
      return
    }
    reportError(error)
  })

  const {
    sheets,
    ratio,
    prepared,
    preparing,
    textPending,
    doc,
    passwordRequest,
    submitPassword,
    cancelPassword,
  } = usePdfSheets({
    pdfUrl,
    enabled: usePdf,
    pageIndex,
    rasterWidth: CURL_RASTER_WIDTH,
    sizing: bookView ? 'uniform' : 'per-page',
    // Search and read-aloud both need page text; extraction rides the raster.
    extractText: true,
    // The flip book owns every leaf at once, so it keeps the page cap. The
    // flat views only hold pages near the reading position — a 700-page
    // document stays cheap there.
    windowRadius: bookView ? undefined : 5,
    maxPages: bookView ? CURL_MAX_PAGES : undefined,
    maxPagesMessage: `This document is longer than ${CURL_MAX_PAGES} pages — the flip book can't hold it, but the other premier views can.`,
    onError: reportSheetsError,
    errorMessage: 'This PDF could not be opened for the premier reader.',
  })

  const bookDisabled = usePdf && doc !== null && doc.numPages > CURL_MAX_PAGES

  const faces = useMemo(
    () => buildPremierFaces({ usePdf, sheets, pages, appearance }),
    [appearance, pages, sheets, usePdf],
  )

  const totalPages = usePdf ? (sheets?.length ?? 0) : pages.length

  const textFor = useCallback(
    (index: number) => {
      if (usePdf) return sheets?.[index]?.text ?? ''
      const page = pages[index]
      return page ? pageSearchText(page) : ''
    },
    [pages, sheets, usePdf],
  )

  const {
    speaking,
    toggle: toggleSpeech,
    stop: stopSpeech,
  } = useReadAloud({
    totalPages,
    pageIndex,
    textFor,
    onPageChange: reportPageChange,
  })

  // Page-level search: a raster leaf cannot highlight a hit, so results name
  // the pages worth turning to.
  const needle = query.trim().toLowerCase()
  const matches = useMemo<PageMatch[]>(() => {
    if (!needle) return []
    if (usePdf) {
      return (sheets ?? [])
        .map((sheet, index) => ({ sheet, index }))
        .filter(({ sheet }) => sheet.text.toLowerCase().includes(needle))
        .map(({ index }) => ({ index, label: `Page ${index + 1}` }))
    }
    return pages
      .map((page, index) => ({ page, index }))
      .filter(({ page }) => pageSearchText(page).toLowerCase().includes(needle))
      .map(({ page, index }) => ({
        index,
        label: page.title ?? `Page ${page.pageNumber}`,
      }))
  }, [needle, pages, sheets, usePdf])
  const shownMatches = matches.slice(0, MATCH_CHIP_LIMIT)

  const openSearch = useCallback(() => setSearchOpen(true), [])
  const closeSearch = useCallback(() => {
    setQuery('')
    setSearchOpen(false)
  }, [])

  useEffect(() => {
    if (searchOpen) searchInputRef.current?.focus()
  }, [searchOpen])

  // The engine owns its overlays, so it answers `/`, mod+F, and Escape
  // through the shell's shortcut channel.
  useEffect(() => {
    const ref = engineShortcutsRef
    ref.current = {
      search: openSearch,
      zoomIn,
      zoomOut,
      zoomReset,
      dismiss: () => {
        if (searchOpen) {
          closeSearch()
          return true
        }
        if (thumbsOpen) {
          setThumbsOpen(false)
          return true
        }
        return false
      },
    }
    return () => {
      ref.current = {}
    }
  }, [
    closeSearch,
    engineShortcutsRef,
    openSearch,
    searchOpen,
    thumbsOpen,
    zoomIn,
    zoomOut,
    zoomReset,
  ])

  useEffect(() => {
    if (usePdf) {
      if (!sheets) return
      reportReady({
        totalPages: sheets.length,
        capabilities: premierCapabilities(source, true),
      })
      return
    }
    if (pages.length === 0) {
      if (source.allowPdfUpload) {
        // Upload affordance, not an error — the empty state below renders the
        // picker, and a zero-page ready keeps the viewport out of "loading".
        reportReady({
          totalPages: 0,
          capabilities: {
            ...DEFAULT_CAPABILITIES,
            pagination: false,
            upload: true,
            appearance: false,
            sound: false,
          },
        })
        return
      }
      reportError({
        kind: 'empty',
        message: 'The premier reader needs page data or a PDF.',
      })
      return
    }
    reportReady({
      totalPages: pages.length,
      capabilities: premierCapabilities(source, false),
    })
  }, [pages.length, reportError, reportReady, sheets, source, usePdf])

  // A password prompt still counts as "open": reporting a zero-page ready
  // unblocks the viewport so the gate is visible, and pagination stays off
  // until the document's real page count arrives.
  useEffect(() => {
    if (!passwordRequest) return
    reportReady({
      totalPages: 0,
      capabilities: {
        ...DEFAULT_CAPABILITIES,
        pagination: false,
        appearance: false,
        sound: false,
        download: false,
      },
    })
  }, [passwordRequest, reportReady])

  // The author's outline becomes the table of contents — a second ready call
  // so a slow bookmark walk never delays the first page.
  useEffect(() => {
    if (!doc) return
    let cancelled = false
    void resolvePdfOutline(doc).then((contents) => {
      if (cancelled || contents.length === 0) return
      reportReady({
        totalPages: doc.numPages,
        capabilities: premierCapabilities(source, true),
        contents,
      })
    })
    return () => {
      cancelled = true
    }
  }, [doc, reportReady, source])

  // A new document stops its narration — a side effect belongs in an effect,
  // not in the render-adjust below.
  const contentIdentity = usePdf ? sheets : pages
  useEffect(() => {
    return () => stopSpeech()
  }, [contentIdentity, stopSpeech])

  // A new document drops its search state too.
  const [prevSheets, setPrevSheets] = useState(sheets)
  const [prevPages, setPrevPages] = useState(pages)
  if (prevSheets !== sheets || prevPages !== pages) {
    setPrevSheets(sheets)
    setPrevPages(pages)
    setQuery('')
    setSearchOpen(false)
    setThumbsOpen(false)
  }

  const searchReady = usePdf ? Boolean(sheets) : pages.length > 0
  const speechDisabled = !hasSpeechSupport() || totalPages === 0

  const controls = (
    <div className="flex flex-wrap items-center justify-center gap-2">
      <p className="text-muted-foreground max-w-[10rem] truncate text-xs sm:max-w-none">
        {source.pdfFileName ?? source.title ?? 'Document'}
      </p>
      <ToggleGroup
        value={[view]}
        onValueChange={(value) => {
          if (value[0]) setViewPref(value[0] as PremierView)
        }}
        variant="outline"
        size="sm"
        spacing={0}
        aria-label="Reader view"
      >
        <ToggleGroupItem
          value="book"
          aria-label="Flip book view"
          disabled={bookDisabled}
          title={
            bookDisabled
              ? `The flip book holds up to ${CURL_MAX_PAGES} pages — this document is longer`
              : 'Flip book'
          }
        >
          <BookOpenIcon />
        </ToggleGroupItem>
        <ToggleGroupItem
          value="single"
          aria-label="Single page"
          title="Single page"
        >
          <RectangleVerticalIcon />
        </ToggleGroupItem>
        <ToggleGroupItem
          value="spread"
          aria-label="Two-page spread"
          title="Two-page spread"
        >
          <Columns2Icon />
        </ToggleGroupItem>
        <ToggleGroupItem
          value="scroll"
          aria-label="Continuous scroll"
          title="Continuous scroll"
        >
          <ScrollIcon />
        </ToggleGroupItem>
        <ToggleGroupItem
          value="text"
          aria-label="Text only"
          title="Text only — the lightest way to read"
        >
          <TypeIcon />
        </ToggleGroupItem>
      </ToggleGroup>
      {searchOpen ? (
        <div className="flex items-center gap-1">
          <div className="relative">
            <SearchIcon className="text-muted-foreground pointer-events-none absolute top-1/2 left-2 size-3.5 -translate-y-1/2" />
            <Input
              ref={searchInputRef}
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder={usePdf ? 'Search document' : 'Search pages'}
              aria-label={usePdf ? 'Search document' : 'Search pages'}
              className="h-8 w-40 pl-7 text-xs sm:w-52"
              onKeyDown={(event) => {
                if (event.key === 'Enter' && matches.length > 0) {
                  event.preventDefault()
                  // Enter lands on the next match from here, not the top
                  // of the list — search reads forward.
                  const next =
                    matches.find((match) => match.index >= pageIndex) ??
                    matches[0]
                  reportPageChange(next.index, 'instant')
                }
                if (event.key === 'Escape') {
                  event.preventDefault()
                  closeSearch()
                  event.currentTarget.blur()
                }
              }}
            />
          </div>
          <span
            className="text-muted-foreground min-w-[5ch] text-center font-mono text-xs"
            aria-live="polite"
            title={textPending ? 'Still indexing the document' : undefined}
          >
            {needle
              ? preparing
                ? '…'
                : `${matches.length}${textPending ? '+' : ''} ${matches.length === 1 ? 'page' : 'pages'}`
              : ''}
          </span>
          <Button
            type="button"
            variant="ghost"
            size="icon-sm"
            aria-label="Close search"
            onClick={closeSearch}
            data-book-preview-press
          >
            <XIcon />
          </Button>
        </div>
      ) : (
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          aria-label={usePdf ? 'Search document' : 'Search pages'}
          aria-keyshortcuts="/ Control+F"
          disabled={!searchReady}
          onClick={openSearch}
          data-book-preview-press
          className="min-h-11 min-w-11 sm:min-h-7 sm:min-w-7"
        >
          <SearchIcon />
        </Button>
      )}
      <Button
        type="button"
        variant="ghost"
        size="icon-sm"
        aria-label="Zoom out"
        aria-keyshortcuts="-"
        onClick={zoomOut}
        disabled={zoom <= 0.6}
        data-book-preview-press
        className="min-h-11 min-w-11 sm:min-h-7 sm:min-w-7"
      >
        <ZoomOutIcon />
      </Button>
      <button
        type="button"
        aria-label="Reset zoom"
        aria-keyshortcuts="0"
        onClick={zoomReset}
        data-book-preview-press
        className="text-muted-foreground hover:text-foreground min-w-[5ch] text-center font-mono text-xs transition-colors"
      >
        {Math.round(zoom * 100)}%
      </button>
      <Button
        type="button"
        variant="ghost"
        size="icon-sm"
        aria-label="Zoom in"
        aria-keyshortcuts="+"
        onClick={zoomIn}
        disabled={zoom >= 2.4}
        data-book-preview-press
        className="min-h-11 min-w-11 sm:min-h-7 sm:min-w-7"
      >
        <ZoomInIcon />
      </Button>
      <Button
        type="button"
        variant={speaking ? 'secondary' : 'ghost'}
        size="icon-sm"
        aria-label={speaking ? 'Stop reading aloud' : 'Read aloud'}
        aria-pressed={speaking}
        disabled={speechDisabled}
        title={
          speaking
            ? 'Stop reading aloud'
            : 'Read aloud — turns the pages itself'
        }
        onClick={toggleSpeech}
        data-book-preview-press
        className="min-h-11 min-w-11 sm:min-h-7 sm:min-w-7"
      >
        {speaking ? <SquareIcon /> : <SpeechIcon />}
      </Button>
      {usePdf && doc && doc.numPages > 1 ? (
        <Button
          type="button"
          variant={thumbsOpen ? 'secondary' : 'ghost'}
          size="icon-sm"
          aria-label="Page thumbnails"
          aria-pressed={thumbsOpen}
          onClick={() => setThumbsOpen((open) => !open)}
          data-book-preview-press
          className="min-h-11 min-w-11 sm:min-h-7 sm:min-w-7"
        >
          <PanelLeftIcon />
        </Button>
      ) : null}
      <span className="sr-only" role="status" aria-live="polite">
        {speaking ? `Reading page ${pageIndex + 1}` : ''}
      </span>
    </div>
  )

  return (
    <div className="flex h-full w-full flex-col gap-3 p-4">
      {chromeHost ? createPortal(controls, chromeHost) : controls}
      <div className="bg-muted/30 flex min-h-0 flex-1 overflow-hidden rounded-lg border">
        {usePdf && doc ? (
          narrow ? (
            <PdfThumbSheet
              doc={doc}
              pageIndex={pageIndex}
              open={thumbsOpen}
              onOpenChange={setThumbsOpen}
              onSelect={(index) => reportPageChange(index, 'instant')}
            />
          ) : (
            <PdfThumbRail
              doc={doc}
              pageIndex={pageIndex}
              open={thumbsOpen}
              onSelect={(index) => reportPageChange(index, 'instant')}
            />
          )
        ) : null}
        <div className="relative min-w-0 flex-1">
          {usePdf && !sheets ? (
            passwordRequest ? (
              <div className="flex h-full items-center justify-center p-4">
                <PdfPasswordGate
                  fileName={source.pdfFileName}
                  incorrect={passwordRequest.incorrect}
                  onSubmit={submitPassword}
                  onCancel={cancelPassword}
                />
              </div>
            ) : pdfUrl ? (
              <div className="text-muted-foreground flex h-full items-center justify-center gap-2 text-sm">
                <Spinner />
                Opening PDF…
              </div>
            ) : (
              <div className="text-muted-foreground flex h-full items-center justify-center text-sm">
                Waiting for a document
              </div>
            )
          ) : !usePdf && pages.length === 0 ? (
            source.allowPdfUpload ? (
              <div className="flex h-full flex-col items-center justify-center gap-3 p-4 text-center">
                <FileUpIcon className="text-muted-foreground/60 size-8" />
                <p className="text-muted-foreground max-w-52 text-sm">
                  Upload or drop a PDF to begin
                </p>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => fileInputRef.current?.click()}
                  data-book-preview-press
                >
                  Choose file
                </Button>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="application/pdf,.pdf"
                  className="hidden"
                  aria-label="Upload PDF"
                  onChange={(event) => {
                    const file = event.target.files?.[0]
                    if (file) uploadPdf(file)
                    event.target.value = ''
                  }}
                />
              </div>
            ) : (
              <div className="text-muted-foreground flex h-full items-center justify-center text-sm">
                Waiting for pages
              </div>
            )
          ) : view === 'book' ? (
            // CSS `zoom` resizes the whole flip stage — layout and pointer
            // math stay consistent, so corner drags still land.
            <div className="h-full w-full" style={{ zoom }}>
              <CurlStage
                pageIndex={pageIndex}
                pageRatio={
                  usePdf ? (ratio ?? CURL_PAGE_RATIO) : CURL_PAGE_RATIO
                }
                canGoPrev={pageIndex > 0}
                canGoNext={pageIndex < Math.max(totalPages, 1) - 1}
                reducedMotion={reducedMotion}
                soundEnabled={soundEnabled}
                contentKey={
                  usePdf
                    ? `pdf:${sheets?.length ?? 0}`
                    : `${appearance}:${pages.map((page) => page.id).join(',')}`
                }
                onPageChange={reportPageChange}
                onEngineError={(message) =>
                  reportError({ kind: 'engine-load', message })
                }
              >
                <PremierSheets
                  usePdf={usePdf}
                  sheets={sheets}
                  pages={pages}
                  appearance={appearance}
                />
              </CurlStage>
            </div>
          ) : view === 'spread' ? (
            <PremierSpreadView
              faces={faces}
              pageIndex={pageIndex}
              zoom={zoom}
              reducedMotion={reducedMotion}
              doc={doc}
              onZoom={setZoom}
              onPageChange={reportPageChange}
            />
          ) : view === 'scroll' ? (
            <PremierScrollView
              faces={faces}
              pageIndex={pageIndex}
              zoom={zoom}
              reducedMotion={reducedMotion}
              doc={doc}
              onZoom={setZoom}
              onPageChange={reportPageChange}
            />
          ) : view === 'text' ? (
            <PremierTextView
              faces={faces}
              pageIndex={pageIndex}
              zoom={zoom}
              reducedMotion={reducedMotion}
              onZoom={setZoom}
              onPageChange={reportPageChange}
            />
          ) : (
            <PremierSingleView
              faces={faces}
              pageIndex={pageIndex}
              zoom={zoom}
              reducedMotion={reducedMotion}
              doc={doc}
              onZoom={setZoom}
              onPageChange={reportPageChange}
            />
          )}
          {preparing && sheets ? (
            <PdfPreparingBadge prepared={prepared} total={sheets.length} />
          ) : null}
          {searchOpen && needle ? (
            <div
              className="bg-background/90 absolute inset-x-0 bottom-0 flex max-h-24 flex-wrap justify-center gap-1.5 overflow-auto border-t p-2 backdrop-blur-sm"
              aria-live="polite"
            >
              {matches.length === 0 ? (
                <p className="text-muted-foreground text-xs">
                  {usePdf && preparing
                    ? 'Still reading the document…'
                    : 'No pages match.'}
                </p>
              ) : (
                <>
                  {shownMatches.map((match) => (
                    <Button
                      key={match.index}
                      type="button"
                      size="xs"
                      variant={
                        match.index === pageIndex ? 'secondary' : 'outline'
                      }
                      onClick={() => reportPageChange(match.index, 'instant')}
                      data-book-preview-press
                    >
                      {match.label}
                    </Button>
                  ))}
                  {matches.length > shownMatches.length ? (
                    <span className="text-muted-foreground self-center text-xs">
                      +{matches.length - shownMatches.length} more
                    </span>
                  ) : null}
                </>
              )}
            </div>
          ) : null}
        </div>
      </div>
    </div>
  )
}

'use client'

import { spreadSlots, spreadStep } from './premier-math'
import { usePageArrival } from '../hooks/use-page-arrival'
import type { BookPreviewNavigationBehavior } from '../types'
import { useStableHandler } from '../hooks/use-stable-handler'
import { useEffect, useRef, useState, type ReactNode } from 'react'
import { FALLBACK_ASPECT, type PremierFace } from './premier-faces'
import {
  renderPdfTextLayer,
  resolvePdfPageLinks,
  type PdfDocumentProxy,
  type PdfPageLink,
} from '../pdf-runtime'

/**
 * The premier reader's flat views — one page, a two-page spread, a continuous
 * strip, and a plain-text flow — all drawn from the same face list the flip
 * book uses. Page-data sources hand over React leaves; PDF sources hand over
 * raster sheets that fill in (and release) around the reading position, with
 * a live text/link overlay so the copy underneath is still selectable.
 */

/**
 * The selectable layer a flat-view PDF face wears: pdf.js's real text layer
 * plus resolved link annotations, positioned over the raster at the face's
 * measured display scale. Work only happens while the face is near the
 * viewport, so a long scroll never builds hundreds of span layers at once —
 * and a ResizeObserver re-renders on zoom so the overlay never drifts.
 */
function PdfFaceOverlay({
  doc,
  pageNumber,
  hasRaster,
  zoom,
  onNavigate,
}: {
  doc: PdfDocumentProxy
  pageNumber: number
  /** The text layer over an unrendered skeleton would float over blank
      paper — wait for the bitmap. */
  hasRaster: boolean
  /** The view's CSS zoom — clientWidth already includes it, so the layer
      renders at the unzoomed scale and the ancestor's zoom carries it. */
  zoom: number
  onNavigate: (index: number, behavior?: BookPreviewNavigationBehavior) => void
}) {
  const hostRef = useRef<HTMLDivElement | null>(null)
  // No IntersectionObserver → treat every face as near and let the paint
  // effect do the work. Not rendered into markup, so hydration is safe.
  const [near, setNear] = useState(
    () => typeof IntersectionObserver === 'undefined',
  )
  const [links, setLinks] = useState<PdfPageLink[]>([])
  const reportNavigate = useStableHandler(onNavigate)

  useEffect(() => {
    const host = hostRef.current
    if (!host || typeof IntersectionObserver === 'undefined') return
    // Generous margin: spans exist a little before the face scrolls in, and
    // disappear a little after it leaves — fast scrolling never sees a gap.
    const observer = new IntersectionObserver(
      ([entry]) => setNear(entry.isIntersecting),
      { rootMargin: '120%' },
    )
    observer.observe(host)
    return () => observer.disconnect()
  }, [])

  useEffect(() => {
    const host = hostRef.current
    if (!host || !near || !hasRaster) return
    let cancelled = false
    let layer: { cancel: () => void } | null = null
    let timer = 0

    const paint = async () => {
      try {
        const page = await doc.getPage(pageNumber)
        if (cancelled) return
        const base = page.getViewport({ scale: 1 })
        const scale = host.clientWidth / (zoom * Math.max(1, base.width))
        if (!Number.isFinite(scale) || scale <= 0) return
        host.replaceChildren()
        host.style.setProperty('--total-scale-factor', String(scale))
        const rendered = await renderPdfTextLayer({
          page,
          container: host,
          scale,
        })
        if (cancelled) {
          rendered.cancel()
          return
        }
        layer = rendered
        const pageLinks = await resolvePdfPageLinks({ page, doc, scale })
        if (!cancelled) setLinks(pageLinks)
      } catch {
        // A page that cannot yield a layer reads as image-only — fine.
      }
    }

    void paint()
    const observer = new ResizeObserver(() => {
      window.clearTimeout(timer)
      timer = window.setTimeout(() => void paint(), 160)
    })
    observer.observe(host)
    return () => {
      cancelled = true
      window.clearTimeout(timer)
      observer.disconnect()
      layer?.cancel()
      host.replaceChildren()
      setLinks([])
    }
  }, [doc, hasRaster, near, pageNumber, zoom])

  return (
    <>
      <div ref={hostRef} className="textLayer" data-book-preview-text-layer />
      {links.length > 0 ? (
        <div
          data-book-preview-links
          className="pointer-events-none absolute inset-0 z-20"
        >
          {links.map((link) => {
            const target = link.target
            const linkKey = `${link.left},${link.top},${link.width}x${link.height}`
            return target.kind === 'page' ? (
              <button
                key={linkKey}
                type="button"
                className="absolute cursor-pointer rounded-sm"
                style={{
                  left: link.left,
                  top: link.top,
                  width: link.width,
                  height: link.height,
                }}
                aria-label={`Go to page ${target.pageIndex + 1}`}
                title={`Go to page ${target.pageIndex + 1}`}
                data-book-preview-link
                data-book-preview-press
                onClick={() => reportNavigate(target.pageIndex, 'instant')}
              />
            ) : (
              <a
                key={linkKey}
                className="absolute cursor-pointer rounded-sm"
                style={{
                  left: link.left,
                  top: link.top,
                  width: link.width,
                  height: link.height,
                }}
                href={target.url}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={`Open link: ${target.url}`}
                title={target.url}
                data-book-preview-link
              />
            )
          })}
        </div>
      ) : null}
    </>
  )
}

/** A face sized by its own aspect — height-bounded so it never outgrows the
    stage, width-bounded so a tall page never overflows narrow screens. */
function FaceBox({
  face,
  className,
  arrival,
  children,
}: {
  face: PremierFace
  className?: string
  arrival?: Record<string, unknown>
  children?: ReactNode
}) {
  return (
    <div
      {...arrival}
      className={
        'bg-card relative h-full max-w-full shrink-0 overflow-hidden rounded-md border shadow-sm ' +
        (className ?? '')
      }
      style={{ aspectRatio: `${face.aspect ?? FALLBACK_ASPECT}` }}
    >
      {face.content}
      {children}
    </div>
  )
}

/** Two-finger pinch scales the face and keeps the document point under the
    midpoint anchored — the same contract the pdf engine's pinch uses. The
    zoom style is written directly during the gesture (no React churn per
    move) and committed to state once the fingers lift. */
function usePinchZoom({
  hostRef,
  zoomTargetRef,
  scrollerRef,
  zoom,
  onZoom,
}: {
  hostRef: React.RefObject<HTMLElement | null>
  /** The element carrying the CSS zoom — measured with rects so the anchor
      math is independent of how browsers report zoomed scroll offsets. */
  zoomTargetRef: React.RefObject<HTMLElement | null>
  scrollerRef: React.RefObject<HTMLElement | null>
  zoom: number
  onZoom: (zoom: number) => void
}) {
  const report = useStableHandler(onZoom)
  const zoomRef = useRef(zoom)
  useEffect(() => {
    zoomRef.current = zoom
  })

  useEffect(() => {
    const host = hostRef.current
    if (!host) return
    const pts = new Map<number, { x: number; y: number }>()
    let pinching = false
    let startDist = 0
    let baseZoom = 1
    let applied = 1

    const dist = () => {
      const [p, q] = [...pts.values()]
      return Math.hypot(p.x - q.x, p.y - q.y)
    }
    const mid = () => {
      const [p, q] = [...pts.values()]
      return { x: (p.x + q.x) / 2, y: (p.y + q.y) / 2 }
    }

    const onDown = (event: PointerEvent) => {
      if (event.pointerType === 'mouse') return
      pts.set(event.pointerId, { x: event.clientX, y: event.clientY })
      if (pts.size === 2) {
        pinching = true
        startDist = dist()
        baseZoom = zoomRef.current
        applied = baseZoom
      }
    }
    const onMove = (event: PointerEvent) => {
      const point = pts.get(event.pointerId)
      if (!point) return
      point.x = event.clientX
      point.y = event.clientY
      if (!pinching || pts.size !== 2 || startDist <= 0) return
      const el = zoomTargetRef.current
      if (!el) return
      const next = Math.min(2.4, Math.max(0.6, baseZoom * (dist() / startDist)))
      const scroller = scrollerRef.current
      // Fraction-of-face anchoring: where the midpoint sits inside the face
      // before the zoom is where it should sit after — convention-free, since
      // getBoundingClientRect is always in visual pixels.
      const m = mid()
      const before = el.getBoundingClientRect()
      const relX = (m.x - before.left) / Math.max(1, before.width)
      const relY = (m.y - before.top) / Math.max(1, before.height)
      el.style.zoom = String(next)
      if (scroller) {
        const after = el.getBoundingClientRect()
        scroller.scrollLeft += after.left + relX * after.width - m.x
        scroller.scrollTop += after.top + relY * after.height - m.y
      }
      applied = next
    }
    const onUp = (event: PointerEvent) => {
      pts.delete(event.pointerId)
      if (pinching && pts.size < 2) {
        pinching = false
        if (Math.abs(applied - zoomRef.current) > 0.005) report(applied)
      }
    }

    host.addEventListener('pointerdown', onDown)
    host.addEventListener('pointermove', onMove)
    host.addEventListener('pointerup', onUp)
    host.addEventListener('pointercancel', onUp)
    return () => {
      host.removeEventListener('pointerdown', onDown)
      host.removeEventListener('pointermove', onMove)
      host.removeEventListener('pointerup', onUp)
      host.removeEventListener('pointercancel', onUp)
    }
  }, [hostRef, report, scrollerRef, zoomTargetRef])
}

/** Horizontal drag on touch/pen turns the view: the face tracks the finger,
    past ~18% width it commits to the view's step target, otherwise it springs
    home. Edge taps on mouse do the same stepping. Zoomed faces hand the drag
    back to native panning — a magnified page scrolls, it does not turn. */
function useSwipeTurn({
  hostRef,
  faceRef,
  stepFor,
  zoom,
  reducedMotion,
  onPageChange,
}: {
  hostRef: React.RefObject<HTMLElement | null>
  faceRef: React.RefObject<HTMLElement | null>
  /** The face index a turn in `direction` should land on — null at the ends.
      Single view steps one face; spread view steps a whole pair. */
  stepFor: (direction: 1 | -1) => number | null
  zoom: number
  reducedMotion: boolean
  onPageChange: (
    index: number,
    behavior?: BookPreviewNavigationBehavior,
  ) => void
}) {
  const report = useStableHandler(onPageChange)
  const gesture = useRef<{
    id: number
    startX: number
    dx: number
    moved: boolean
  } | null>(null)
  // A drag that moved swallows its own trailing click so the edge-tap zones
  // cannot double-fire a turn the swipe already committed.
  const suppressClick = useRef(false)
  const stateRef = useRef({ stepFor, zoom, reducedMotion })
  useEffect(() => {
    stateRef.current = { stepFor, zoom, reducedMotion }
  })

  useEffect(() => {
    const host = hostRef.current
    if (!host) return

    const settle = (el: HTMLElement, target: string, ms: number) => {
      if (stateRef.current.reducedMotion) {
        el.style.translate = target
        return
      }
      el.style.transition = `translate ${ms}ms ease-out`
      el.style.translate = target
      window.setTimeout(() => {
        el.style.transition = ''
      }, ms)
    }
    const release = () => {
      const face = faceRef.current
      if (face) {
        face.style.transition = ''
        face.style.translate = ''
      }
    }

    const onDown = (event: PointerEvent) => {
      if (event.pointerType === 'mouse' || event.button !== 0) return
      // A second finger means pinch — release the swipe so the zoom gesture
      // owns the face instead of stacking translate on it.
      if (gesture.current) {
        gesture.current = null
        release()
        return
      }
      // Zoomed pages pan natively; a drag must not also turn the page.
      if (stateRef.current.zoom !== 1) return
      if ((event.target as HTMLElement).closest('a,button,input,[role=button]'))
        return
      gesture.current = {
        id: event.pointerId,
        startX: event.clientX,
        dx: 0,
        moved: false,
      }
      host.setPointerCapture(event.pointerId)
    }
    const onMove = (event: PointerEvent) => {
      const active = gesture.current
      if (!active || event.pointerId !== active.id) return
      const dx = event.clientX - active.startX
      active.dx = dx
      if (Math.abs(dx) > 6) active.moved = true
      const face = faceRef.current
      if (!face) return
      // Rubber-band when the step target does not exist.
      const target = stateRef.current.stepFor(dx < 0 ? 1 : -1)
      face.style.translate = `${target === null ? dx * 0.35 : dx}px 0`
    }
    const onUp = (event: PointerEvent) => {
      const active = gesture.current
      if (!active || event.pointerId !== active.id) return
      gesture.current = null
      suppressClick.current = active.moved
      const face = faceRef.current
      const width = host.clientWidth || 1
      const dx = active.dx
      const commit = Math.abs(dx) > Math.min(80, width * 0.18)
      const target = commit ? stateRef.current.stepFor(dx < 0 ? 1 : -1) : null
      if (face) {
        settle(
          face,
          commit && target !== null
            ? `${dx < 0 ? -width : width}px 0`
            : '0px 0',
          commit && target !== null ? 140 : 160,
        )
      }
      if (target !== null) report(target)
    }
    // A browser-interrupted gesture springs home — it can never turn.
    const onCancel = (event: PointerEvent) => {
      const active = gesture.current
      if (!active || event.pointerId !== active.id) return
      gesture.current = null
      suppressClick.current = active.moved
      release()
    }
    // Edge taps (mouse) step the same way — the outer ~18% is a turn zone.
    const onClick = (event: MouseEvent) => {
      if (suppressClick.current) {
        suppressClick.current = false
        return
      }
      if ((event.target as HTMLElement).closest('a,button,input,[role=button]'))
        return
      const rect = host.getBoundingClientRect()
      const ratio = (event.clientX - rect.left) / Math.max(rect.width, 1)
      const direction = ratio < 0.18 ? -1 : ratio > 0.82 ? 1 : null
      if (direction === null) return
      const target = stateRef.current.stepFor(direction)
      if (target !== null) report(target)
    }

    host.addEventListener('pointerdown', onDown)
    host.addEventListener('pointermove', onMove)
    host.addEventListener('pointerup', onUp)
    host.addEventListener('pointercancel', onCancel)
    host.addEventListener('click', onClick)
    return () => {
      host.removeEventListener('pointerdown', onDown)
      host.removeEventListener('pointermove', onMove)
      host.removeEventListener('pointerup', onUp)
      host.removeEventListener('pointercancel', onCancel)
      host.removeEventListener('click', onClick)
    }
  }, [faceRef, hostRef, report])
}

/** One face at a time — the phone-friendly view and the default on narrow
    screens. Drag left/right or use the reader's arrows to turn. */
export function PremierSingleView({
  faces,
  pageIndex,
  zoom,
  reducedMotion,
  doc,
  onZoom,
  onPageChange,
}: {
  faces: PremierFace[]
  pageIndex: number
  zoom: number
  reducedMotion: boolean
  /** The open pdf document — present only for pdf sources; page-data faces
      are already real DOM text and need no overlay. */
  doc: PdfDocumentProxy | null
  onZoom: (zoom: number) => void
  onPageChange: (
    index: number,
    behavior?: BookPreviewNavigationBehavior,
  ) => void
}) {
  const hostRef = useRef<HTMLDivElement | null>(null)
  const scrollerRef = useRef<HTMLDivElement | null>(null)
  const faceRef = useRef<HTMLDivElement | null>(null)
  const arrival = usePageArrival(pageIndex)
  useSwipeTurn({
    hostRef,
    faceRef,
    stepFor: (direction) => {
      const next = pageIndex + direction
      return next >= 0 && next < faces.length ? next : null
    },
    zoom,
    reducedMotion,
    onPageChange,
  })
  usePinchZoom({
    hostRef,
    zoomTargetRef: faceRef,
    scrollerRef,
    zoom,
    onZoom,
  })

  const face = faces[Math.min(pageIndex, faces.length - 1)]
  return (
    <div
      ref={hostRef}
      className={
        zoom === 1
          ? 'h-full w-full touch-pan-y'
          : 'h-full w-full touch-pan-x touch-pan-y'
      }
    >
      {/* m-auto centers the face but top-aligns it the moment it overflows,
          so a zoomed page scrolls instead of clipping its head. */}
      <div ref={scrollerRef} className="flex h-full overflow-auto p-4">
        <div
          ref={faceRef}
          style={{ zoom }}
          className="m-auto h-[min(62svh,100%)]"
        >
          {face ? (
            <FaceBox face={face} arrival={arrival} key={face.key}>
              {doc && face.pageNumber !== null ? (
                <PdfFaceOverlay
                  doc={doc}
                  pageNumber={face.pageNumber}
                  hasRaster={face.hasRaster}
                  zoom={zoom}
                  onNavigate={onPageChange}
                />
              ) : null}
            </FaceBox>
          ) : null}
        </div>
      </div>
    </div>
  )
}

/** Two faces side by side — the magazine/atlas view. Advances a pair at a
    time; the cover stands alone. */
export function PremierSpreadView({
  faces,
  pageIndex,
  zoom,
  reducedMotion,
  doc,
  onZoom,
  onPageChange,
}: {
  faces: PremierFace[]
  pageIndex: number
  zoom: number
  reducedMotion: boolean
  doc: PdfDocumentProxy | null
  onZoom: (zoom: number) => void
  onPageChange: (
    index: number,
    behavior?: BookPreviewNavigationBehavior,
  ) => void
}) {
  const hostRef = useRef<HTMLDivElement | null>(null)
  const scrollerRef = useRef<HTMLDivElement | null>(null)
  const faceRef = useRef<HTMLDivElement | null>(null)
  const { pair, left, right } = spreadSlots(pageIndex, faces.length)
  const arrival = usePageArrival(pair)
  useSwipeTurn({
    hostRef,
    faceRef,
    stepFor: (direction) => spreadStep(pair, direction, faces.length),
    zoom,
    reducedMotion,
    onPageChange,
  })
  usePinchZoom({
    hostRef,
    zoomTargetRef: faceRef,
    scrollerRef,
    zoom,
    onZoom,
  })

  const leftFace = faces[left]
  const rightFace = right >= 0 ? faces[right] : null
  return (
    <div
      ref={hostRef}
      className={
        zoom === 1
          ? 'h-full w-full touch-pan-y'
          : 'h-full w-full touch-pan-x touch-pan-y'
      }
    >
      <div ref={scrollerRef} className="flex h-full overflow-auto p-4">
        <div
          ref={faceRef}
          style={{ zoom }}
          className="m-auto flex h-[min(56svh,100%)] items-stretch gap-0.5"
        >
          {leftFace ? (
            <FaceBox face={leftFace} arrival={arrival} key={leftFace.key}>
              {doc && leftFace.pageNumber !== null ? (
                <PdfFaceOverlay
                  doc={doc}
                  pageNumber={leftFace.pageNumber}
                  hasRaster={leftFace.hasRaster}
                  zoom={zoom}
                  onNavigate={onPageChange}
                />
              ) : null}
            </FaceBox>
          ) : null}
          {rightFace ? (
            <FaceBox face={rightFace} arrival={arrival} key={rightFace.key}>
              {doc && rightFace.pageNumber !== null ? (
                <PdfFaceOverlay
                  doc={doc}
                  pageNumber={rightFace.pageNumber}
                  hasRaster={rightFace.hasRaster}
                  zoom={zoom}
                  onNavigate={onPageChange}
                />
              ) : null}
            </FaceBox>
          ) : leftFace ? (
            <div
              aria-hidden
              className="bg-muted/30 h-full shrink-0 rounded-md"
              style={{
                aspectRatio: `${leftFace.aspect ?? FALLBACK_ASPECT}`,
              }}
            />
          ) : null}
        </div>
      </div>
    </div>
  )
}

/**
 * Scroll position → page index, for the continuous views. The element with
 * the largest visible share is "current" — that also steers the pdf raster
 * window. External navigation (thumbs, contents, arrows, search) scrolls the
 * target into view, but never when the reader's own scroll put it there, so
 * the two can never fight.
 */
function useScrollPageSync({
  scrollerRef,
  pageIndex,
  count,
  reducedMotion,
  onPageChange,
}: {
  scrollerRef: React.RefObject<HTMLElement | null>
  pageIndex: number
  count: number
  reducedMotion: boolean
  onPageChange: (
    index: number,
    behavior?: BookPreviewNavigationBehavior,
  ) => void
}) {
  const faceEls = useRef(new Map<number, HTMLElement>())
  const ratios = useRef(new Map<number, number>())
  const dominantRef = useRef(pageIndex)
  const report = useStableHandler(onPageChange)

  useEffect(() => {
    const host = scrollerRef.current
    if (!host || typeof IntersectionObserver === 'undefined') return
    // A new face list must not inherit the last document's visibility scores.
    ratios.current.clear()
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          const index = Number((entry.target as HTMLElement).dataset.faceIndex)
          ratios.current.set(
            index,
            entry.isIntersecting ? entry.intersectionRatio : 0,
          )
        }
        let best = -1
        let bestRatio = 0.1
        for (const [index, ratio] of ratios.current) {
          if (ratio > bestRatio) {
            best = index
            bestRatio = ratio
          }
        }
        if (best >= 0 && best < count && best !== dominantRef.current) {
          dominantRef.current = best
          report(best, 'instant')
        }
      },
      { root: host, threshold: [0.1, 0.35, 0.6, 0.85] },
    )
    for (const el of faceEls.current.values()) observer.observe(el)
    return () => observer.disconnect()
  }, [count, report, scrollerRef])

  useEffect(() => {
    if (dominantRef.current === pageIndex) return
    const el = faceEls.current.get(pageIndex)
    if (!el) return
    dominantRef.current = pageIndex
    el.scrollIntoView({
      block: 'start',
      behavior: reducedMotion ? 'auto' : 'smooth',
    })
  }, [pageIndex, reducedMotion])

  return (index: number) => (el: HTMLElement | null) => {
    if (el) faceEls.current.set(index, el)
    else faceEls.current.delete(index)
  }
}

/** Every face in one continuous strip — the document view. */
export function PremierScrollView({
  faces,
  pageIndex,
  zoom,
  reducedMotion,
  doc,
  onZoom,
  onPageChange,
}: {
  faces: PremierFace[]
  pageIndex: number
  zoom: number
  reducedMotion: boolean
  doc: PdfDocumentProxy | null
  onZoom: (zoom: number) => void
  onPageChange: (
    index: number,
    behavior?: BookPreviewNavigationBehavior,
  ) => void
}) {
  const scrollerRef = useRef<HTMLDivElement | null>(null)
  const columnRef = useRef<HTMLDivElement | null>(null)
  const registerFace = useScrollPageSync({
    scrollerRef,
    pageIndex,
    count: faces.length,
    reducedMotion,
    onPageChange,
  })
  usePinchZoom({
    hostRef: scrollerRef,
    zoomTargetRef: columnRef,
    scrollerRef,
    zoom,
    onZoom,
  })

  return (
    <div
      ref={scrollerRef}
      className="h-full w-full overflow-auto overscroll-contain"
    >
      <div
        ref={columnRef}
        className="mx-auto flex w-[88%] max-w-[44rem] flex-col items-stretch gap-4 py-6"
        style={{ zoom }}
      >
        {faces.map((face, index) => (
          <div
            key={face.key}
            data-face-index={index}
            ref={registerFace(index)}
            className="bg-card relative w-full overflow-hidden rounded-md border shadow-sm"
            style={{ aspectRatio: `${face.aspect ?? FALLBACK_ASPECT}` }}
          >
            {face.content}
            {doc && face.pageNumber !== null ? (
              <PdfFaceOverlay
                doc={doc}
                pageNumber={face.pageNumber}
                hasRaster={face.hasRaster}
                zoom={zoom}
                onNavigate={onPageChange}
              />
            ) : null}
          </div>
        ))}
      </div>
    </div>
  )
}

